-- Run with the canonical appointment-payments and ambulance fixtures retained in
-- the SAME outer rollback transaction. See the payment setup guide / test runner.
-- All gateway identifiers and responses here are synthetic. No provider calls.
BEGIN;
DO $$
DECLARE a clinzo.appointment; c clinzo.appointment_charge; patient_actor uuid; patient_auth uuid; doctor_auth uuid;
 practice uuid; recipient uuid; attempt uuid; cash_attempt uuid; entry uuid; cash_entry uuid;
 details jsonb; result jsonb; transfer jsonb; reversal jsonb; refund_key uuid; refund_job uuid;
 booking uuid; cash_booking uuid; driver_key uuid; driver_actor uuid; driver_auth uuid; quote_id uuid; payment_attempt uuid; payment_key uuid;
 denied boolean; configured_version bigint; receipt_id uuid;
BEGIN
 SELECT a0.* INTO a FROM clinzo.appointment a0 WHERE a0.reason='Cash fixture' ORDER BY a0.created_at DESC LIMIT 1;
 IF a.id IS NULL THEN RAISE EXCEPTION 'Run appointment-payment fixture in this transaction first'; END IF;
 SELECT s.doctor_facility_id,i.subject::uuid INTO practice,doctor_auth FROM clinzo.session s JOIN clinzo.doctor d ON d.id=s.doctor_id JOIN clinzo.identity i ON i.id=d.identity_id WHERE s.id=a.session_id;
 SELECT pa.identity_id,i.subject::uuid INTO patient_actor,patient_auth FROM clinzo.patient_access pa JOIN clinzo.identity i ON i.id=pa.identity_id WHERE pa.patient_id=a.patient_id AND pa.verified_at IS NOT NULL LIMIT 1;
 SELECT * INTO c FROM clinzo.appointment_charge WHERE id=clinzo.appointment_charge_id(a.id);
 PERFORM set_config('request.jwt.claim.sub',patient_auth::text,true);
 IF public.has_company_finance_access() OR jsonb_array_length(public.list_payout_entries())<>0 THEN RAISE EXCEPTION 'Patient accessed provider finance'; END IF;
 denied:=false;
 BEGIN PERFORM public.manage_company_payments('config',jsonb_build_object('note','Unauthorized settings')); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'Patient changed company settings'; END IF;
 INSERT INTO clinzo.company_reviewer(identity_id) VALUES(patient_actor) ON CONFLICT(identity_id) DO UPDATE SET active=true;
 INSERT INTO clinzo.company_finance_member(identity_id) VALUES(patient_actor);
 SELECT row_version INTO configured_version FROM clinzo.marketplace_payment_config WHERE singleton;
 PERFORM public.manage_company_payments('config',jsonb_build_object('enabled',true,'mode','test','appointmentBps',1000,'ambulanceBps',1000,'releaseDelayHours',0,'expectedVersion',configured_version,'note','Synthetic 10 percent test policy'));
 denied:=false;
 BEGIN PERFORM public.manage_company_payments('config',jsonb_build_object('enabled',true,'mode','test','appointmentBps',2000,'ambulanceBps',1000,'releaseDelayHours',0,'expectedVersion',configured_version,'note','Stale fixture')); EXCEPTION WHEN SQLSTATE 'PT409' THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'Stale commission settings accepted'; END IF;
 result:=public.manage_company_payments('recipient',jsonb_build_object('scopeKind','practice','scopeId',practice,'payeeKind','doctor','legalName','Synthetic doctor recipient','accountId','acc_FixtureDoctor','productId','acc_prd_FixtureDoctor','note','Synthetic recipient agreement checked'));
 recipient:=(result->>'id')::uuid;
 PERFORM public.payout_provider_command('verify_recipient',jsonb_build_object('recipient_id',recipient,'mode','test','entity',jsonb_build_object('id','acc_prd_FixtureDoctor','account_id','acc_FixtureDoctor','product_name','route','activation_status','activated','tnc',jsonb_build_object('accepted',true))));
 UPDATE clinzo.appointment SET status='confirmed',capacity_released_at=NULL,recovery_outcome=NULL WHERE id=a.id;
 INSERT INTO clinzo.appointment_payment_attempt(charge_id,method,amount_minor,status,payment_id,order_id) VALUES(c.id,'gateway',10000,'captured','pay_FixtureDoctor','order_FixtureDoctor') RETURNING id INTO attempt;
 SELECT id INTO entry FROM clinzo.payout_entry WHERE appointment_attempt_id=attempt;
 details:=clinzo.payout_details(entry);
 IF (details->>'company_minor')::bigint<>1000 OR (details->>'provider_minor')::bigint<>9000 THEN RAISE EXCEPTION 'Wrong commission split'; END IF;
 IF public.payout_provider_command('claim_transfer',jsonb_build_object('entry_id',entry,'mode','test')) IS NOT NULL THEN RAISE EXCEPTION 'Transfer before consultation completion'; END IF;
 UPDATE clinzo.appointment SET status='completed' WHERE id=a.id;
 result:=public.payout_provider_command('claim_transfer',jsonb_build_object('entry_id',entry,'mode','test'));
 IF result IS NULL OR (result->>'transfer_minor')::bigint<>9000 THEN RAISE EXCEPTION 'Completed consultation not payable: %, claim %',clinzo.payout_details(entry),result; END IF;
 IF public.payout_provider_command('claim_transfer',jsonb_build_object('entry_id',entry,'mode','test')) IS NOT NULL THEN RAISE EXCEPTION 'Transfer claimed twice'; END IF;
 PERFORM public.payout_provider_command('transfer_uncertain',jsonb_build_object('entry_id',entry,'mode','test'));
 IF public.payout_provider_command('claim_transfer',jsonb_build_object('entry_id',entry,'mode','test')) IS NOT NULL THEN RAISE EXCEPTION 'Uncertain transfer replayed'; END IF;
 transfer:=jsonb_build_object('id','trf_FixtureDoctor','source','pay_FixtureDoctor','recipient','acc_FixtureDoctor','currency','INR','amount',9000,'amount_reversed',0,'status','processed','settlement_status','pending','notes',jsonb_build_object('entry_id',entry::text));
 denied:=false;
 BEGIN PERFORM public.payout_provider_command('transfer_result',jsonb_build_object('entry_id',entry,'mode','test','entity',transfer||jsonb_build_object('amount',9001))); EXCEPTION WHEN invalid_parameter_value THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'Wrong transfer amount accepted'; END IF;
 PERFORM public.payout_provider_command('transfer_result',jsonb_build_object('entry_id',entry,'mode','test','entity',transfer));
 details:=clinzo.payout_details(entry);
 IF details->>'settlement_status'<>'pending' OR details->>'transfer_status'<>'processed' THEN RAISE EXCEPTION 'Transfer confused with bank settlement'; END IF;
 PERFORM public.payout_provider_command('transfer_result',jsonb_build_object('entry_id',entry,'mode','test','entity',transfer||jsonb_build_object('settlement_status','settled','recipient_settlement_id','setl_Fixture')));
 IF clinzo.payout_details(entry)->>'settlement_status'<>'settled' THEN RAISE EXCEPTION 'Bank settlement not recorded'; END IF;
 UPDATE clinzo.marketplace_payment_config SET appointment_bps=2000 WHERE singleton;
 IF (clinzo.payout_details(entry)->>'commission_bps')::integer<>1000 THEN RAISE EXCEPTION 'Historical commission changed'; END IF;
 -- An approved surplus refund reduces the liability before provider POST.
 INSERT INTO clinzo.appointment_refund_request(charge_id,kind,status,amount_minor,deduction_minor,reason,requested_by) VALUES(c.id,'surplus','approved',2000,0,'Synthetic surplus',patient_actor) RETURNING id INTO refund_key;
 INSERT INTO clinzo.appointment_refund_job(refund_id,attempt_id,amount_minor) VALUES(refund_key,attempt,2000) RETURNING id INTO refund_job;
 denied:=false;
 BEGIN PERFORM public.appointment_provider_command('claim_refund',jsonb_build_object('job_id',refund_job)); EXCEPTION WHEN SQLSTATE 'PT409' THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'Refund preceded provider reversal'; END IF;
 reversal:=public.payout_provider_command('claim_reversal',jsonb_build_object('entry_id',entry,'mode','test'));
 IF reversal IS NULL OR (reversal->>'amount_minor')::bigint<>1800 THEN RAISE EXCEPTION 'Incorrect proportional reversal'; END IF;
 PERFORM public.payout_provider_command('reversal_result',jsonb_build_object('entry_id',entry,'mode','test','reversal_id',reversal->>'id','entity',jsonb_build_object('id','rvrsl_Fixture','transfer_id','trf_FixtureDoctor','amount',1800,'currency','INR','notes',jsonb_build_object('reversal_id',reversal->>'id'))));
 IF public.payout_provider_command('claim_reversal',jsonb_build_object('entry_id',entry,'mode','test')) IS NOT NULL THEN RAISE EXCEPTION 'Reversal repeated before cumulative transfer refresh'; END IF;
 transfer:=transfer||jsonb_build_object('amount_reversed',1800,'status','partially_reversed');
 PERFORM public.payout_provider_command('transfer_result',jsonb_build_object('entry_id',entry,'mode','test','entity',transfer));
 result:=public.appointment_provider_command('claim_refund',jsonb_build_object('job_id',refund_job));
 IF result IS NULL THEN RAISE EXCEPTION 'Refund blocked after verified reversal'; END IF;
 PERFORM public.appointment_provider_command('refund_result',jsonb_build_object('job_id',refund_job,'entity',jsonb_build_object('id','rfnd_FixtureDoctor','payment_id','pay_FixtureDoctor','amount',2000,'currency','INR','receipt',refund_job::text,'status','processed')));
 IF (clinzo.payout_details(entry)->>'provider_minor')::bigint<>7200 THEN RAISE EXCEPTION 'Refund counted twice in payout balance'; END IF;
 INSERT INTO clinzo.appointment_payment_attempt(charge_id,method,amount_minor,status) VALUES(c.id,'cash',10000,'captured') RETURNING id INTO cash_attempt;
 SELECT id INTO cash_entry FROM clinzo.payout_entry WHERE appointment_attempt_id=cash_attempt;
 result:=public.manage_company_payments('cash_receipt',jsonb_build_object('entryId',cash_entry,'expectedAmount',2000,'reference','fixture-company-cash','note','Company actually received commission'));
 receipt_id:=(result->>'id')::uuid;
 IF (public.manage_company_payments('cash_receipt',jsonb_build_object('entryId',cash_entry,'expectedAmount',2000,'reference','fixture-company-cash','note','Repeated confirmation'))->>'id')::uuid<>receipt_id THEN RAISE EXCEPTION 'Repeated cash commission duplicated'; END IF;
 IF (clinzo.payout_details(cash_entry)->>'cash_due_minor')::bigint<>0 OR (SELECT count(*) FROM clinzo.cash_commission_receipt WHERE entry_id=cash_entry)<>1 THEN RAISE EXCEPTION 'Cash commission reconciliation incorrect'; END IF;
 -- Driver fixture is produced by the canonical ambulance smoke workflow.
 SELECT b.id,aa.driver_id,d.identity_id,i.subject::uuid INTO booking,driver_key,driver_actor,driver_auth FROM clinzo.ambulance_booking b JOIN clinzo.trip t ON t.booking_id=b.id JOIN clinzo.ambulance_assignment aa ON aa.id=t.assignment_id JOIN clinzo.driver d ON d.id=aa.driver_id JOIN clinzo.identity i ON i.id=d.identity_id WHERE b.pickup_address='Fixture pickup near hospital' AND t.status='completed' ORDER BY b.created_at DESC LIMIT 1;
 IF booking IS NULL THEN RAISE EXCEPTION 'Run canonical ambulance fixture first'; END IF;
 result:=public.manage_company_payments('recipient',jsonb_build_object('scopeKind','driver','scopeId',driver_key,'payeeKind','operator','legalName','Synthetic operator recipient','accountId','acc_FixtureDriver','productId','acc_prd_FixtureDriver','note','Operator payment arrangement checked'));
 recipient:=(result->>'id')::uuid;
 PERFORM public.payout_provider_command('verify_recipient',jsonb_build_object('recipient_id',recipient,'mode','test','entity',jsonb_build_object('id','acc_prd_FixtureDriver','account_id','acc_FixtureDriver','product_name','route','activation_status','activated','tnc',jsonb_build_object('accepted',true))));
 result:=public.manage_company_payments('final_fare',jsonb_build_object('bookingId',booking,'amountMinor',100000,'note','Synthetic agreed trip fare'));
 quote_id:=(result->>'id')::uuid;
 SELECT i.subject::uuid INTO patient_auth FROM clinzo.ambulance_booking b JOIN clinzo.identity i ON i.id=b.requested_by WHERE b.id=booking;
 PERFORM set_config('request.jwt.claim.sub',patient_auth::text,true);
 result:=public.prepare_ambulance_payment(booking,quote_id); payment_attempt:=(result->>'id')::uuid; payment_key:=(result->>'payment_id')::uuid;
 -- Exercise both worker branches: record variables must not shadow SQL aliases.
 IF jsonb_typeof(public.ambulance_provider_command('queue',jsonb_build_object('mode','test')))<>'array' THEN RAISE EXCEPTION 'Ambulance worker queue must return an array'; END IF;
 result:=public.ambulance_provider_command('work',jsonb_build_object('booking_id',booking,'mode','test'));
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result) item WHERE item->>'id'=payment_attempt::text AND (item->>'amount_minor')::bigint=100000) THEN RAISE EXCEPTION 'Ambulance worker did not load the correct attempt and amount'; END IF;
 IF (public.prepare_ambulance_payment(booking,quote_id)->>'id')::uuid<>payment_attempt THEN RAISE EXCEPTION 'Ambulance checkout duplicated'; END IF;
 PERFORM public.ambulance_provider_command('claim_order',jsonb_build_object('attempt_id',payment_attempt,'mode','test'));
 IF public.ambulance_provider_command('claim_order',jsonb_build_object('attempt_id',payment_attempt,'mode','test')) IS NOT NULL THEN RAISE EXCEPTION 'Ambulance order claimed twice'; END IF;
 PERFORM public.ambulance_provider_command('order_ready',jsonb_build_object('attempt_id',payment_attempt,'mode','test','entity',jsonb_build_object('id','order_FixtureDriver','receipt',payment_attempt::text,'amount',100000,'currency','INR')));
 PERFORM set_config('request.jwt.claim.sub',driver_auth::text,true);
 denied:=false;
 BEGIN PERFORM public.record_ambulance_cash(booking,quote_id,100000,'Duplicate cash after online order'); EXCEPTION WHEN SQLSTATE 'PT409' THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'Cash duplicated pending gateway collection'; END IF;
 PERFORM public.ambulance_provider_command('payment',jsonb_build_object('mode','test','entity',jsonb_build_object('id','pay_FixtureDriver','order_id','order_FixtureDriver','amount',100000,'currency','INR','status','captured','captured',true,'amount_refunded',0)));
 IF public.get_ambulance_billing(booking)->>'status'<>'paid' THEN RAISE EXCEPTION 'Ambulance capture not recorded'; END IF;
 SELECT id INTO entry FROM clinzo.payout_entry WHERE ambulance_payment_id=payment_key;
 IF (clinzo.payout_details(entry)->>'provider_minor')::bigint<>90000 OR (SELECT count(*) FROM jsonb_array_elements(public.list_payout_entries()) x WHERE x->>'id'=entry::text)<>1 THEN RAISE EXCEPTION 'Driver payout scope/split incorrect'; END IF;
 IF has_function_privilege('authenticated','public.payout_provider_command(text,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public.ambulance_provider_command(text,jsonb)','EXECUTE') OR has_table_privilege('authenticated','clinzo.payout_entry','SELECT') THEN RAISE EXCEPTION 'Payout grants exposed'; END IF;
END $$;
SELECT true AS marketplace_payment_workflow_passed;
ROLLBACK;
